/**
 * Task data record holding a task's text, done state, creation time and optional due date.
 * @trace DSN-005 REQ-001 REQ-002 REQ-007 REQ-009 REQ-010
 */
export interface Task {
  id: string;
  text: string;
  done: boolean;
  createdAt: number;
  dueDate: string | null;
}

import { Task } from './Task.js';

/**
 * A Task as returned by the list route, with the server computed overdue flag.
 * @trace DSN-009 REQ-010
 */
export interface TaskView extends Task {
  overdue: boolean;
}

import { DatabaseSync } from 'node:sqlite';
import { Task } from './Task.js';

type Row = { id: string; text: string; done: number; createdAt: number; dueDate: string | null };

function toTask(r: Row): Task {
  return { id: r.id, text: r.text, done: r.done === 1, createdAt: r.createdAt, dueDate: r.dueDate ?? null };
}

/**
 * SQLite persistence of tasks inside the service process, including the nullable due date.
 *
 * @trace DSN-008 REQ-003 REQ-006 REQ-009
 */
export class TaskStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, text TEXT NOT NULL, done INTEGER NOT NULL, createdAt INTEGER NOT NULL, dueDate TEXT)'
    );
    // Databases created before due dates existed lack the column.
    const cols = this.db.prepare('PRAGMA table_info(tasks)').all() as unknown as { name: string }[];
    if (!cols.some((c) => c.name === 'dueDate')) {
      this.db.exec('ALTER TABLE tasks ADD COLUMN dueDate TEXT');
    }
  }

  /** Returns all stored tasks ordered by creation time. */
  async findAll(): Promise<Task[]> {
    const rows = this.db
      .prepare('SELECT id, text, done, createdAt, dueDate FROM tasks ORDER BY createdAt, id')
      .all() as unknown as Row[];
    return rows.map(toTask);
  }

  /** Returns the task with the given id, or null when it is not stored. */
  async findById(id: string): Promise<Task | null> {
    const rows = this.db
      .prepare('SELECT id, text, done, createdAt, dueDate FROM tasks WHERE id = ?')
      .all(id) as unknown as Row[];
    const r = rows[0];
    return r ? toTask(r) : null;
  }

  /** Inserts a new task; throws when the id is already stored. */
  async insert(task: Task): Promise<void> {
    this.db
      .prepare('INSERT INTO tasks (id, text, done, createdAt, dueDate) VALUES (?, ?, ?, ?, ?)')
      .run(task.id, task.text, task.done ? 1 : 0, task.createdAt, task.dueDate);
  }

  /** Updates a stored task's fields; throws when the task is not stored. */
  async update(task: Task): Promise<void> {
    const result = this.db
      .prepare('UPDATE tasks SET text = ?, done = ?, createdAt = ?, dueDate = ? WHERE id = ?')
      .run(task.text, task.done ? 1 : 0, task.createdAt, task.dueDate, task.id);
    if (Number(result.changes) === 0) {
      throw new Error(`Task ${task.id} not found`);
    }
  }

  /** Deletes the task with the given id; throws when the id is empty. */
  async delete(id: string): Promise<void> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
    this.db.prepare('DELETE FROM tasks WHERE id = ?').run(id);
  }
}

import { randomUUID } from 'node:crypto';
import { Task } from './Task.js';
import { TaskStore } from './TaskStore.js';
import { TaskView } from './TaskView.js';

const MAX_TEXT_LENGTH = 200;

function isValidDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const d = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === value;
}

/**
 * Validates task text and due date, applies the task rules and orders the task list.
 * @trace DSN-007 REQ-001 REQ-002 REQ-005 REQ-006 REQ-007 REQ-009 REQ-010
 */
export class TaskService {
  constructor(private readonly taskStore: TaskStore) {}

  /** Returns all tasks with overdue flags, open first, each group oldest first; throws on an invalid today. */
  async list(today: string | undefined): Promise<TaskView[]> {
    const day = today ?? new Date().toISOString().slice(0, 10);
    if (typeof day !== 'string' || !isValidDate(day)) {
      throw new Error('today must be a date in the form YYYY-MM-DD');
    }
    const tasks = await this.taskStore.findAll();
    return [...tasks]
      .sort((a, b) => {
        if (a.done !== b.done) {
          return a.done ? 1 : -1;
        }
        return a.createdAt - b.createdAt;
      })
      .map((t) => ({ ...t, overdue: this.isOverdue(t, day) }));
  }

  /** True only for an open task whose due date is strictly before today. */
  isOverdue(task: Task, today: string): boolean {
    return !task.done && task.dueDate !== null && task.dueDate < today;
  }

  /** Adds a new not-done task; throws if the text or due date is invalid. */
  async add(text: string, dueDate: string | null): Promise<Task> {
    const task: Task = {
      id: randomUUID(),
      text: this.normalizeText(text),
      done: false,
      createdAt: Date.now(),
      dueDate: this.normalizeDueDate(dueDate),
    };
    await this.taskStore.insert(task);
    return task;
  }

  /** Sets the done state of a task; throws if the id is invalid or the task is not found. */
  async setDone(id: string, done: boolean): Promise<Task> {
    this.checkId(id);
    const task = await this.requireTask(id);
    task.done = done;
    await this.taskStore.update(task);
    return task;
  }

  /** Replaces text and, unless undefined, due date of a task; throws if invalid or the task is not found. */
  async editText(id: string, text: string, dueDate: string | null | undefined): Promise<Task> {
    this.checkId(id);
    const normalized = this.normalizeText(text);
    const due = dueDate === undefined ? undefined : this.normalizeDueDate(dueDate);
    const task = await this.requireTask(id);
    task.text = normalized;
    if (due !== undefined) {
      task.dueDate = due;
    }
    await this.taskStore.update(task);
    return task;
  }

  /** Deletes a task; throws if the id is invalid or the task is not found. */
  async remove(id: string): Promise<void> {
    this.checkId(id);
    await this.requireTask(id);
    await this.taskStore.delete(id);
  }

  /** Trims the text and returns it; throws if it is empty or longer than 200 characters after trimming. */
  normalizeText(text: string): string {
    if (typeof text !== 'string') {
      throw new Error('text must be a string');
    }
    const trimmed = text.trim();
    if (trimmed.length === 0) {
      throw new Error('Text must not be empty');
    }
    if (trimmed.length > MAX_TEXT_LENGTH) {
      throw new Error(`Text must be at most ${MAX_TEXT_LENGTH} characters`);
    }
    return trimmed;
  }

  /** Returns null for no due date or the valid YYYY-MM-DD date; throws for anything else. */
  normalizeDueDate(dueDate: string | null): string | null {
    if (dueDate === null || dueDate === '') {
      return null;
    }
    if (typeof dueDate !== 'string' || !isValidDate(dueDate)) {
      throw new Error('dueDate must be a valid date in the form YYYY-MM-DD');
    }
    return dueDate;
  }

  private checkId(id: string): void {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
  }

  private async requireTask(id: string): Promise<Task> {
    const task = await this.taskStore.findById(id);
    if (task === null) {
      throw new Error(`Task ${id} not found`);
    }
    return task;
  }
}

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { Task } from './Task.js';
import { TaskService } from './TaskService.js';
import { TaskView } from './TaskView.js';

const PAGE_PATH = fileURLToPath(new URL('../../public/index.html', import.meta.url));

/**
 * HTTP-facing controller that serves the task page and maps task routes onto TaskService.
 * @trace DSN-006 REQ-001 REQ-002 REQ-004 REQ-005 REQ-006 REQ-007 REQ-008 REQ-009 REQ-010
 */
export class TaskController {
  constructor(private readonly taskService: TaskService) {}

  /** Returns the HTML of public/index.html; throws when the file cannot be read. */
  async page(): Promise<string> {
    return readFile(PAGE_PATH, 'utf8');
  }

  /** Returns all tasks with overdue flags for the given date; throws on an invalid date. */
  async list(today: string | undefined): Promise<TaskView[]> {
    return this.taskService.list(today);
  }

  /** Adds a task from body.text and optional body.dueDate; throws when either is invalid. */
  async create(body: { text: string; dueDate?: string | null; }): Promise<Task> {
    if (typeof body?.text !== 'string') {
      throw new Error('text must be a string');
    }
    return this.taskService.add(body.text, body.dueDate ?? null);
  }

  /** Updates text, due date and/or done state of task id and returns it; throws when id is invalid or no field is given. */
  async update(id: string, body: { text?: string; done?: boolean; dueDate?: string | null; }): Promise<Task> {
    this.checkId(id);
    if (body?.text === undefined && body?.done === undefined && body?.dueDate === undefined) {
      throw new Error('text, done or dueDate is required');
    }
    if (body.done !== undefined && typeof body.done !== 'boolean') {
      throw new Error('done must be a boolean');
    }
    let task: Task | undefined;
    if (body.text !== undefined || body.dueDate !== undefined) {
      let text = body.text;
      if (text === undefined) {
        // Only the due date changes: keep the stored text.
        const current = (await this.taskService.list(undefined)).find((t) => t.id === id);
        if (!current) {
          throw new Error(`Task ${id} not found`);
        }
        text = current.text;
      }
      task = await this.taskService.editText(id, text, body.dueDate);
    }
    if (body.done !== undefined) {
      task = await this.taskService.setDone(id, body.done);
    }
    return task as Task;
  }

  /** Deletes task id; throws when id is invalid. */
  async remove(id: string): Promise<void> {
    this.checkId(id);
    await this.taskService.remove(id);
  }

  private checkId(id: string): void {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
  }
}

import express, { Express, NextFunction, Request, Response } from 'express';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import { TaskStore } from '../tasks-app/TaskStore.js';
import { TaskService } from '../tasks-app/TaskService.js';
import { TaskController } from '../tasks-app/TaskController.js';

export function createApp(db: DatabaseSync = new DatabaseSync(':memory:')): Express {
  const taskStore = new TaskStore(db);
  const taskService = new TaskService(taskStore);
  const taskController = new TaskController(taskService);

  const app = express();
  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });
  app.use(express.json());
  app.get('/', async (_req, res) => {
    res.type('html').send(await taskController.page());
  });
  app.use(express.static(fileURLToPath(new URL('../../public', import.meta.url))));

  app.get('/api/tasks', async (req, res) => {
    const today = typeof req.query.today === 'string' ? req.query.today : undefined;
    res.json(await taskController.list(today));
  });
  app.post('/api/tasks', async (req, res) => {
    res.status(201).json(await taskController.create(req.body));
  });
  app.patch('/api/tasks/:id', async (req, res) => {
    res.json(await taskController.update(String(req.params.id), req.body ?? {}));
  });
  app.delete('/api/tasks/:id', async (req, res) => {
    const result = await taskController.remove(String(req.params.id));
    res.status(200).json(result ?? { ok: true });
  });

  app.use((err: Error, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.message.endsWith('not found') ? 404 : 400;
    res.status(status).json({ error: err.message });
  });
  return app;
}

